	[$'         Create the venv from the root of the project: python3 -m venv .venv && .venv/bin/pip install -e ".[dev]"\\n']=$'         Créer le venv depuis la racine du projet : python3 -m venv .venv && .venv/bin/pip install -e ".[dev]"\\n'
