	[$'Development computer: Machin dev opens a shell, venv activated; Machin dev-test runs the checks']=$'Poste de développement : Machin dev ouvre un shell, venv activé ; Machin dev-test lance les vérifications'
	[$'First indexing: Machin indexer, then Machin indexer --full-audit']=$'Première indexation : Machin indexer, puis Machin indexer --full-audit'
	[$'GStreamer version and plugins, audio output']=$'Version et greffons GStreamer, sortie audio'
